class Counter extends Actor {
  var n = 0
  def receive = {
    case Inc      => n += 1
    case Get      => sender() ! n
    case Reset    => context.become(frozen)
  }
  def frozen: Receive = { case Get => sender() ! n }
}

public class PlayerGrain : Grain, IPlayerGrain {
    int score;
    public Task AddScore(int s) { score += s; return Task.CompletedTask; }
}
// caller
var p = client.GetGrain<IPlayerGrain>(playerId);
await p.AddScore(10);   // activated on demand
